/* مسار مراجعة مستقل لكل إدارة، مع حفظ مؤلف المعرفة ومساهمات المراجع. */
const reviewDepartments=[...new Set(Object.values(employees).map(e=>e.dept))];
const workflowLogin=login;
login=function(){return workflowLogin().replace('<div class="field"><label>الرقم الوظيفي',`<div id="reviewDepartmentWrap" class="field hidden"><label>إدارة المراجع (تجريبي)</label><select id="reviewDepartment" class="input">${reviewDepartments.map(d=>`<option>${escapeKnowledge(d)}</option>`).join('')}</select></div><div class="field"><label>الرقم الوظيفي`);};
const workflowSetRole=setLoginRole;
setLoginRole=function(r){workflowSetRole(r);document.getElementById('reviewDepartmentWrap').classList.toggle('hidden',r!=='reviewer');};
const workflowDoLogin=doLogin;
doLogin=function(){if(loginRole==='reviewer')state.reviewerDepartment=document.getElementById('reviewDepartment').value;workflowDoLogin();};
const workflowEmployeeHome=employeeHome;
function reviewerPanelContent(){
 const tab=state.reviewerHomeTab||'review';
 const html=tab==='reference'?referenceImpact():tab==='impact'?impact():workflowReviewerHome();
 const start=html.indexOf('<main class="container">')+'<main class="container">'.length,end=html.lastIndexOf('</main>');
 return html.slice(start,end).replace(/<div class="page-back">[\s\S]*$/, '');
}
function reviewerWorkspace(){const selected=state.reviewerHomeTab||'review';return `<section class="reviewer-workspace"><div class="reviewer-home-tabs" role="tablist" aria-label="مساحة المراجع">${[['review','مراجعة معارف إدارتي'],['reference','أثري المرجعي'],['impact','أثري المعرفي']].map(([key,label])=>`<button id="reviewer-tab-${key}" class="reviewer-home-tab ${selected===key?'active':''}" role="tab" aria-selected="${selected===key}" aria-controls="reviewer-home-panel" onclick="selectReviewerHomeTab('${key}')">${label}</button>`).join('')}</div><div id="reviewer-home-panel" role="tabpanel" aria-labelledby="reviewer-tab-${selected}">${reviewerPanelContent()}</div></section>`;}
function selectReviewerHomeTab(tab){if(state.role!=='reviewer'||!['review','reference','impact'].includes(tab))return;state.reviewerHomeTab=tab;save();document.querySelector('.reviewer-workspace').outerHTML=reviewerWorkspace();}
employeeHome=function(){let html=workflowEmployeeHome();
 const points=html.match(/<div class="home-points-row">([\s\S]*?)<\/div>/);
 if(points){html=html.replace(points[0],'');html=html.replace(/(<div class="page-head"><div>[\s\S]*?<\/div>)<\/div>/,'$1'+points[0]+'</div>');}
 if(state.role==='reviewer'){const start=html.indexOf('<div class="home-lower">'),end=html.lastIndexOf('</main>');if(start>=0)html=html.slice(0,start)+reviewerWorkspace()+html.slice(end);}
 return html;
};
const workflowReviewerHome=reviewerHome;
reviewerHome=function(){return workflowReviewerHome().replace('<main class="container">','<main class="container"><div class="actions"><button class="btn btn-primary" onclick="go(\'employee-home\')">خدمات المنصة</button><button class="btn btn-outline" onclick="go(\'reference-impact\')">أثري المرجعي</button></div>');};
const workflowNotifications=visibleNotifications;
visibleNotifications=function(){if(state.role==='reviewer')return [...(state.notifications.reviewer||[]).map((n,index)=>({n,index})).filter(({n})=>canReview(state.knowledge.find(k=>k.id===n.id))),...(state.notifications.employee||[]).map((n,index)=>({n,index:-(index+1)})).filter(({n})=>n.recipientId===currentPersonId())];return workflowNotifications();};
const workflowOpenNotification=openNotification;
openNotification=function(index){if(index<0){const n=state.notifications.employee[-index-1];state.notifOpen=false;go(n.type==='returned'?'edit':'detail',n.id);return;}workflowOpenNotification(index);};
function reviewEditModal(id){const k=state.knowledge.find(k=>k.id===id);if(!canReview(k)||k.status!=='review')return;const fields=[['title','عنوان المعرفة',k.title],['challenge','الموقف أو التحدي',k.challenge],['handling','كيف تم التعامل معه؟',k.handling],['solution','الحل الذي نجح — خطوة في كل سطر',k.solution.join('\n')],['lesson','الدرس المستفاد',k.lesson]];showModal('تعديل واستكمال المعرفة','يبقى النشر باسم الموظف، وتُحفظ مساهمتك في أثرك المرجعي.',`<form class="review-edit-form" onsubmit="saveReviewContribution(event,${id})"><div class="review-edit-fields">${fields.map(([key,label,value])=>`<div class="field"><label>${label}</label><textarea id="review-${key}" class="textarea" required>${escapeKnowledge(value)}</textarea></div>`).join('')}<div class="field"><label>وصف مساهمتك</label><textarea id="review-note" class="textarea" required placeholder="ما الذي عدّلته أو استكملته؟"></textarea></div></div><div class="review-edit-save"><button class="btn btn-primary">حفظ التعديلات</button></div></form>`);modal.querySelector('.modal').classList.add('review-edit-modal');}
function saveReviewContribution(e,id){e.preventDefault();const k=state.knowledge.find(k=>k.id===id);if(!canReview(k)||k.status!=='review')return;const keys=['title','challenge','handling','solution','lesson'],values=keys.map(key=>document.getElementById('review-'+key).value.trim()),note=document.getElementById('review-note').value.trim();if(values.some(v=>!v)||!note)return;if(keys.every((key,i)=>(key==='solution'?k.solution.join('\n'):k[key])===values[i])){notify('لم يتغير محتوى المعرفة');return;}const before=Object.fromEntries(keys.map(key=>[key,k[key]]));keys.forEach((key,i)=>k[key]=key==='solution'?values[i].split('\n').filter(Boolean):values[i]);k.reviewContributions=k.reviewContributions||[];k.reviewContributions.push({reviewerId:currentPersonId(),reviewer:cu().name,department:cu().dept,note,before,date:new Date().toISOString()});save();closeModal();render();notify('تم حفظ التعديل وتوثيق مساهمتك في أثرك المرجعي');}
function reviewTransferSection(k){return `<section class="card review-transfer-section"><h3>تحويل إلى الإدارة المختصة</h3><p class="meta">اختر إدارة واحدة لتحويل المعرفة إلى مراجعها المعرفي. يبقى اسم صاحب المعرفة والإدارات المستهدفة للنشر دون تغيير.</p><form onsubmit="transferReview(event,${k.id})"><div class="department-choices">${reviewDepartments.filter(d=>d!==cu().dept).map(d=>`<label class="review-transfer-choice"><input type="radio" name="transfer-department" value="${escapeKnowledge(d)}" required><span>${escapeKnowledge(d)}</span></label>`).join('')}</div><button class="btn btn-outline" style="margin-top:18px">تحويل للمراجعة</button></form></section>`;}
function transferReview(e,id){e.preventDefault();const k=state.knowledge.find(k=>k.id===id);if(!canReview(k)||k.status!=='review')return;const selected=document.querySelector('[name="transfer-department"]:checked'),dept=selected?.value;if(!reviewDepartments.includes(dept)||dept===cu().dept)return;k.reviewTransfers=k.reviewTransfers||[];k.reviewTransfers.push({from:cu().dept,to:dept,by:currentPersonId(),date:new Date().toISOString()});k.reviewDepartment=dept;addKnowledgeNotification('reviewer',k,'submitted');save();state.reviewerHomeTab='review';go('employee-home');notify('تم تحويل المعرفة إلى مراجع '+dept);}
function referenceImpact(){const list=state.knowledge.filter(k=>(k.reviewContributions||[]).some(c=>c.reviewerId===currentPersonId()));return shell(`${pageHead('أثري المرجعي','مساهماتك في تعديل واستكمال معارف الموظفين، مع بقاء نسبتها إلى أصحابها.')}<div class="card metric"><span>معارف ساهمت في استكمالها</span><strong>${list.length}</strong></div>${list.map(k=>`<article class="card" style="margin-top:18px"><h3>${escapeKnowledge(k.title)}</h3><p>صاحب المعرفة: ${escapeKnowledge(k.owner)}</p><span class="status ${k.status}">${statusText(k.status)}</span>${k.reviewContributions.filter(c=>c.reviewerId===currentPersonId()).map(c=>`<p>${escapeKnowledge(c.note)} · ${escapeKnowledge(c.date.slice(0,10))}</p>`).join('')}</article>`).join('')||'<p>لا توجد مساهمات تعديل بعد.</p>'}`);}
const workflowRender=render;
render=function(){if(state.route==='reference-impact'&&state.role==='reviewer')app.innerHTML=referenceImpact();else workflowRender();};
render();
